/// <summary>
///     The <c>SalesLineBackOrderFrm_GridFilterKCS_PurchRefDate_Extension</c> class is the extension for <c>SalesLineBackOrder</c>
/// </summary>
[ExtensionOf(formControlStr(SalesLineBackOrder, GridFilterKCS_PurchRefDate))]
final class SalesLineBackOrderFrm_GridFilterKCS_PurchRefDate_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean             retVal;
    KCS_PurchRefDate    qValue;

    FormDataSource  locSalesTableDS;
    FormDataSource  locSalesLineDS;

    locSalesTableDS = element.SalesTable_DS;
    locSalesLineDS  = element.SalesLine_DS;

    retVal = next modified();

    qValue = element.GridFilterKCS_PurchRefDate.dateValue();

    if (qValue != dateNull())
    {
        SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, KCS_PurchRefDate)).value(queryValue(qValue));
    }
    else
    {
        SysQuery::findOrCreateRange(locSalesTableDS.queryBuildDataSource(), fieldNum(SalesTable, KCS_PurchRefDate)).value(SysQueryRangeUtil::valueUnlimited());
    }

    locSalesLineDS.executeQuery();

    return retVal;
}
